<?php if($block['assets']):$desktop=$block['assets']['desktop']??$block['assets']['mobile'];$desktopKey=isset($block['assets']['desktop'])?'desktop':'mobile';$assetPage=$isPreview?'home-banner-preview':'home-banner'; ?>
<picture><?php if(isset($block['assets']['mobile'])): ?><source media="(max-width:640px)" srcset="<?= e(url($assetPage,['id'=>$block['id'],'device'=>'mobile','v'=>$homeVersion])) ?>"><?php endif ?><img src="<?= e(url($assetPage,['id'=>$block['id'],'device'=>$desktopKey,'v'=>$homeVersion])) ?>" width="<?= (int)$desktop['width'] ?>" height="<?= (int)$desktop['height'] ?>" alt="<?= e($block['title']) ?>" loading="<?= $index===0?'eager':'lazy' ?>" <?= $index===0?'fetchpriority="high"':'' ?>></picture><?php endif ?>
<div class="hs-banner-copy"><span class="hs-eyebrow">نامیرا · گنجینه‌ای برای یادهای ماندگار</span><h1><?= e($block['title']) ?></h1><?php if($block['description']): ?><p><?= e($block['description']) ?></p><?php endif ?><a class="primary" href="<?= e($more) ?>"><?= e($block['button']) ?> <span aria-hidden="true">←</span></a></div>
<?php if(!$block['assets']): ?><div class="hs-hero-art" aria-hidden="true"><?php if($items):foreach($items as $im): ?><img src="<?= e(url('media',['id'=>$im['id']])) ?>" width="<?= (int)$im['width'] ?>" height="<?= (int)$im['height'] ?>" alt="" loading="<?= $index===0?'eager':'lazy' ?>"><?php endforeach;else: ?><span>ن</span><?php endif ?><small>تصویر، روایتِ ماندگاری</small></div><?php endif ?>
</div>
<?php elseif($type==='request'): ?>
<div class="hs-request-copy"><span class="hs-eyebrow">با هم، حافظِ یک یاد</span><h2><?= e($block['title']) ?></h2><p><?= e($block['description']?:'اگر تصویر شهید موردنظرتان را پیدا نکردید، درخواست طراحی رایگان ثبت کنید.') ?></p></div><a class="primary" href="<?= e(url('request')) ?>">درخواست طراحی رایگان <span aria-hidden="true">←</span></a>
<?php else: ?>
<div class="hs-section-head"><div><span class="hs-eyebrow"><?= e(['images'=>'گالری نامیرا','products'=>'فروشگاه نامیرا','calls'=>'خلق یک روایت تازه','artists'=>'پدیدآورندگان آثار','martyrs'=>'یادشان ماندگار'][$type]) ?></span><h2><?= e($block['title']) ?></h2><?php if($block['description']): ?><p><?= e($block['description']) ?></p><?php endif ?></div><a class="hs-more" href="<?= e($more) ?>">مشاهده همه <span aria-hidden="true">←</span></a></div>
<?php if($type==='images'):view('cards',['images'=>$items]); ?>
<?php elseif($type==='products'): ?><div class="hs-products-grid"><?php foreach($items as $p): ?><article class="hs-product"><a href="<?= e(url('product',['id'=>$p['id']])) ?>"><div class="hs-product-image"><?php if($p['cover_id']||$p['image_id']): ?><img loading="lazy" width="500" height="500" src="<?= e($p['cover_id']?url('store-media',['id'=>$p['cover_id']]):url('media',['id'=>$p['image_id']])) ?>" alt="<?= e($p['title']) ?>"><?php else: ?><span aria-hidden="true">ن</span><?php endif ?></div><h3><?= e($p['title']) ?></h3><p class="hs-price"><?= $p['pricing']==='quote'?'استعلام قیمت':fa(number_format((int)$p['min_price'])).' <small>تومان</small>' ?></p></a></article><?php endforeach ?></div>
<?php elseif($type==='calls'): ?><div class="hs-calls-grid"><?php foreach($items as $c): ?><article class="hs-call"><?php if($c['poster_asset_id']): ?><a class="hs-call-poster" href="<?= e(url('call',['id'=>$c['id']])) ?>"><img loading="lazy" width="600" height="750" src="<?= e(url('asset',['id'=>$c['poster_asset_id']])) ?>" alt="<?= e($c['title']) ?>"></a><?php endif ?><div class="hs-call-copy"><span class="hs-live"><i aria-hidden="true"></i> پذیرای آثار شما</span><h3><?= e($c['title']) ?></h3><?php if(Namira\PublicPresentation::meaningful(strip_tags($c['description']))): ?><p><?= e(mb_substr(strip_tags($c['description']),0,200)) ?></p><?php endif ?><a class="primary" href="<?= e(url('call',['id'=>$c['id']])) ?>">جزئیات و شرکت در فراخوان ←</a></div></article><?php endforeach ?></div>
<?php elseif($type==='artists'): ?><div class="hs-people-row"><?php foreach($items as $a): ?><article class="hs-artist"><a href="<?= e(url('artist',['id'=>$a['id']])) ?>"><?php view('artist-avatar',['artist'=>$a]); ?><h3><?= e($a['display_name']) ?></h3><p><?= e(mb_substr(strip_tags($a['data']['summary']??''),0,110)) ?></p><span>پروفایل و آثار ←</span></a></article><?php endforeach ?></div>
<?php elseif($type==='martyrs'): ?><div class="hs-people-row hs-martyr-row"><?php foreach($items as $m): ?><article class="hs-martyr"><a href="<?= e(url('profile',['id'=>$m['id']])) ?>"><div class="hs-martyr-photo"><?php if($m['cover']): ?><img loading="lazy" src="<?= e(url('media',['id'=>$m['cover']['id']])) ?>" width="400" height="500" alt="<?= e($m['title']) ?>"><?php else: ?><span aria-hidden="true">ن</span><?php endif ?></div><h3>شهید <?= e($m['title']) ?></h3><span>روایت زندگی و تصاویر ←</span></a></article><?php endforeach ?></div><?php endif ?>
<?php endif ?>
</section>
<?php endforeach ?>
<?php if(!$sections): ?><section class="hs-empty"><h1>نامیرا؛ یادها ماندگارند</h1><a class="primary" href="<?= e(url('gallery')) ?>">مشاهده آرشیو تصاویر</a></section><?php endif ?>
</div>
